#!/usr/bin/env node
/*
 * Publish listings exported from the admin ("Export for publishing").
 *
 *   node tools/import-bundle.js path/to/verdant-publish-YYYY-MM-DD.json [--root .]
 *
 * Writes every embedded photo, video, and 360° image to assets/listings/<listing-id>/,
 * rewrites the listing data to point at those files, and regenerates data/listings.js.
 * Commit and push the result to publish.
 */
'use strict';
const fs = require('fs');
const path = require('path');

const args = process.argv.slice(2);
const file = args.find((a) => !a.startsWith('--'));
const rootIdx = args.indexOf('--root');
const root = path.resolve(rootIdx > -1 ? args[rootIdx + 1] : path.join(__dirname, '..'));
if (!file) { console.error('Usage: node tools/import-bundle.js <bundle.json> [--root <site dir>]'); process.exit(1); }

const bundle = JSON.parse(fs.readFileSync(file, 'utf8'));
if (bundle.format !== 'verdant-bundle' || !Array.isArray(bundle.listings)) { console.error('Not a Verdant publishing bundle.'); process.exit(1); }

const EXT = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif', 'video/mp4': 'mp4', 'video/webm': 'webm', 'video/quicktime': 'mov' };
const slug = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40);
const safeId = (s) => (/^[\w-]{1,80}$/.test(s) ? s : slug(s) || 'listing');

let written = 0, bytes = 0;
const listings = bundle.listings.map((raw) => {
  const l = JSON.parse(JSON.stringify(raw));
  const dir = path.join('assets', 'listings', safeId(l.id));
  const used = new Set();
  const place = (ref, label) => {
    const m = bundle.media && bundle.media[ref];
    if (!m) return String(ref).startsWith('idb:') ? null : ref; // keep hosted https links as-is
    const match = /^data:([^;,]+)?(;base64)?,(.*)$/s.exec(m.data || '');
    if (!match) return null;
    const type = match[1] || m.type || 'application/octet-stream';
    const ext = EXT[type] || (path.extname(m.name || '').slice(1).toLowerCase()) || 'bin';
    let base = slug(label) || 'file', name = base + '.' + ext, n = 2;
    while (used.has(name)) name = base + '-' + n++ + '.' + ext;
    used.add(name);
    const buf = match[2] ? Buffer.from(match[3], 'base64') : Buffer.from(decodeURIComponent(match[3]));
    fs.mkdirSync(path.join(root, dir), { recursive: true });
    fs.writeFileSync(path.join(root, dir, name), buf);
    written++; bytes += buf.length;
    return (dir + '/' + name).split(path.sep).join('/');
  };

  const rooms = l.rooms || {};
  const newRooms = {};
  l.photos = (l.photos || []).map((ref, i) => {
    const out = place(ref, 'photo-' + String(i + 1).padStart(2, '0') + (rooms[ref] ? '-' + rooms[ref] : ''));
    if (out && rooms[ref]) newRooms[out] = rooms[ref];
    return out;
  }).filter(Boolean);
  l.rooms = newRooms;
  if (l.video && l.video.ref) { const v = place(l.video.ref, 'video-tour'); l.video = v ? { ref: v } : null; }
  if (l.pano && Array.isArray(l.pano.scenes)) {
    l.pano.scenes = l.pano.scenes.map((s, i) => Object.assign({}, s, { ref: place(s.ref, '360-' + String(i + 1).padStart(2, '0') + '-' + (s.room || 'room')) })).filter((s) => s.ref);
    if (!l.pano.scenes.length) l.pano = null;
  }
  if (l.plan && l.plan.image) { const img = place(l.plan.image, 'floor-plan'); l.plan = img ? Object.assign({}, l.plan, { image: img }) : null; }
  delete l.source;
  return l;
});

const header = '/*\n * Published inventory. Generated by tools/import-bundle.js from an admin export\n * (' + (bundle.exportedAt || 'unknown date') + '). Listings created or edited in admin.html are\n * layered on top of these in that browser until they are exported and published again.\n */\n';
fs.writeFileSync(path.join(root, 'data', 'listings.js'), header + 'window.VERDANT_SEED = ' + JSON.stringify(listings, null, 2) + ';\n');

console.log('Listings: ' + listings.length + ' (' + listings.filter((l) => l.published !== false).length + ' published)');
listings.forEach((l) => console.log('  - ' + (l.title || l.address) + ' — ' + l.address + ': ' + (l.photos || []).length + ' photos' + (l.pano ? ', 360° tour with ' + l.pano.scenes.length + ' rooms' : '') + (l.published === false ? ' [draft]' : '')));
console.log('Media files written: ' + written + ' (' + (bytes / 1048576).toFixed(1) + ' MB) → assets/listings/');
